    func testOffersMatchTheGame() {
        for (n, c) in LevelUpTests.cases.enumerated() {
            let h = Hero(actor: "hero.life_might_male", x: 0, y: 0, movement: 20)
            h.heroClass = c.0; h.level = c.2; h.lastCombatOffer = c.3
            for (i, l) in c.1.enumerated() where l >= 0 { h.skills[RuleTables.skillIds[i]] = l + 1 }
            var w: [String: Int] = [:]
            for (i, k) in RuleTables.skillIds.enumerated() { w[k] = LevelUpTests.weights[c.0][i] }
            var rng = H4Random(seed: c.4)
            let offer = h.levelUpOffer(weights: w, random: &rng)
            XCTAssertEqual(offer.map { [$0.skill, $0.level] }, c.5, "case \(n)")
            XCTAssertEqual(rng.state, c.6, "case \(n) rng")
            XCTAssertEqual(h.lastCombatOffer, c.7, "case \(n) last combat")
        }
    }

    func testExperienceTable() {
        XCTAssertEqual(Array(Hero.experienceTable[1...12]), [0, 1000, 2000, 3200, 4600, 6200, 8100, 10300, 12900, 16000, 19700, 24100])
        XCTAssertEqual(Hero.level(for: 999), 1)
        XCTAssertEqual(Hero.level(for: 3200), 4)
    }

    func testPromotion() {
        let h = Hero(actor: "hero.life_might_male", x: 0, y: 0, movement: 20)
        h.heroClass = 0   // knight with tactics and combat -> general
        h.skills = ["tactics": 3, "offense": 2, "toughness": 2]
        h.reconsiderClass()
        XCTAssertEqual(h.classKeyword, "general")
    }
}
